// 1. 取得上一個節點的資料 (Aggregate 節點)
const input = items[0].json;
const clients = input["客戶名稱"];
const baseLinks = input["加買發票連結"];

// 2. 取得 Line Messaging Trigger 的 userId
// 使用 $item("0") 確保從觸發節點抓到正確的 ID
const userId = $item("0").$node["Line Messaging Trigger"].json.source.userId;

// 3. 動態生成按鈕
const buttons = clients.map((name, index) => {
  const link = baseLinks[index];
  // 串接 uid 參數
  const finalUri = link.includes('?') ? `${link}&uid=${userId}` : `${link}?uid=${userId}`;

  return {
    "type": "button",
    "action": {
      "type": "uri",
      "label": name, 
      "uri": finalUri
    },
    "style": "primary",
    "margin": "sm"
  };
});

// 4. 組裝 Flex Message
const flexContent = {
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "📋 加買發票申請",
        "weight": "bold",
        "size": "lg",
        "color": "#1DB446"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "請選擇對應的單位進行填寫：",
        "size": "sm",
        "color": "#666666",
        "wrap": true,
        "margin": "md"
      },
      ...buttons 
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "如誤按請忽略此訊息",
        "size": "sm",
        "color": "#FF0000",
        "align": "center",
        "weight": "bold"
      }
    ]
  }
};

return {
  flexJsonString: JSON.stringify(flexContent)
};

