// ==========================================
// 1. 自訂公告規則設定 (有特別公告需求時填入，平時維持空陣列 [])
// ==========================================
const customRules = [
  // 範例 1：全天停班/放假公告 (isAllDay 設為 true)
  // { date: "20260907", isAllDay: true, title: "颱風停班公告", badgeText: "🌀 颱風停班", content: "因颱風來襲，依縣市政府規定本日（{DATE}）停止上班上課。期間訊息將於恢復上班後儘速為您處理，造成不便敬請見諒。" },

  // 範例 2：特定時段活動公告 (時段性：填寫 timeRange "1100~1700")
  // { date: "20260908", timeRange: "1100~1700", title: "活動公告", badgeText: "📢 特別公告", content: "您好！為了提供更優質與合規的專業服務，本所同仁今日全體參加洗錢防制研習講座。專員將於明日上班後儘速與您回覆處理。" }
];

// ==========================================
// 2. 日期與時間格式化工具函式
// ==========================================
function formatDateText(dateStr) {
  if (!dateStr) return "";
  if (dateStr.length === 7) return `${dateStr.substring(0,3)}年${dateStr.substring(3,5)}月${dateStr.substring(5,7)}日`;
  if (dateStr.length === 8) return `${dateStr.substring(0,4)}年${dateStr.substring(4,6)}月${dateStr.substring(6,8)}日`;
  return dateStr;
}

function formatTimeText(timeRangeStr) {
  if (!timeRangeStr) return "";
  const times = timeRangeStr.split(/[~～\-]/).map(t => t.trim());
  if (times.length === 2 && times[0].length === 4 && times[1].length === 4) {
    return `${times[0].substring(0,2)}:${times[0].substring(2,4)}～${times[1].substring(0,2)}:${times[1].substring(2,4)}`;
  }
  return timeRangeStr;
}

// ==========================================
// 3. 取得台北時間與目前狀態計算
// ==========================================
const now = new Date();
const formatter = new Intl.DateTimeFormat('zh-TW', { 
  timeZone: 'Asia/Taipei', 
  year: 'numeric', 
  month: '2-digit', 
  day: '2-digit', 
  hour: '2-digit', 
  minute: '2-digit', 
  hour12: false 
});

const parts = Object.fromEntries(formatter.formatToParts(now).map(p => [p.type, p.value]));
const year = parseInt(parts.year);
const monthStr = parts.month;
const dayStr = parts.day;
const taipeiHour = parseInt(parts.hour) % 24;
const taipeiMinute = parseInt(parts.minute);
const currentHM = taipeiHour * 100 + taipeiMinute;

const currentDateCE = `${year}${monthStr}${dayStr}`;
const currentDateROC = `${year - 1911}${monthStr}${dayStr}`;

// 安全讀取 n8n 上游節點輸入
const inputItem = $input.first() ? $input.first().json : {};
const holidayInfo = Array.isArray(inputItem) ? inputItem[0] : inputItem;

// 國定假日與例假日判斷
const isHolidayApi = Boolean(holidayInfo && (holidayInfo.isHoliday === true || holidayInfo.isHoliday === "true" || holidayInfo.isHoliday === "是"));
const isWeekend = (now.getDay() === 0 || now.getDay() === 6);
const isHoliday = isHolidayApi || isWeekend;

// 辦公時間判斷 (08:00～12:00, 13:00～17:00)
const isOfficeHour = (taipeiHour >= 8 && taipeiHour < 17);
const isLunchBreak = (taipeiHour === 12);

// ==========================================
// 4. 自訂規則比對
// ==========================================
let matchedCustomRule = null;
for (const rule of customRules) {
  if (!rule.date || rule.date.trim() === "") continue;
  if (rule.date === currentDateCE || rule.date === currentDateROC) {
    if (rule.isAllDay) {
      matchedCustomRule = rule;
      break;
    } else if (rule.timeRange) {
      const times = rule.timeRange.split(/[~～\-]/).map(t => parseInt(t.trim(), 10));
      if (times.length === 2) {
        const [startHM, endHM] = times;
        if (currentHM >= startHM && currentHM < endHM) { 
          matchedCustomRule = rule; 
          break; 
        }
      }
    }
  }
}

// ==========================================
// 5. 動態主題卡片內容設定 (統一用語為「辦公時間 / 儘速」)
// ==========================================
let displayTitle = "目前為非辦公時間";
let displayContent = "您好！感謝您的訊息。我們已收到您的資訊，將於下一個上班日優先處理，請耐心等候回覆。";
let badgeText = "🌙 非辦公時間";
let badgeColor = "#283593";
let badgeBg = "#E8EAF6";
let themeColor = "#3F51B5";
let isTriggered = false;

if (matchedCustomRule) {
  const formattedDate = formatDateText(matchedCustomRule.date);
  displayTitle = matchedCustomRule.title || "特別公告";
  badgeText = matchedCustomRule.badgeText || "📢 特別公告";
  badgeColor = "#C62828";
  badgeBg = "#FFEBEE";
  themeColor = "#D32F2F";

  if (matchedCustomRule.isAllDay) {
    displayContent = matchedCustomRule.content.replace("{DATE}", formattedDate);
  } else {
    displayContent = `【${formattedDate} ${formatTimeText(matchedCustomRule.timeRange)}】\n${matchedCustomRule.content}`;
  }
  isTriggered = true;
} else if (isHoliday) {
  displayTitle = "今日為國定假日";
  displayContent = "您好！今日適逢國定假日，我們將於恢復上班後儘速處理您的訊息，祝您假期愉快。";
  badgeText = "🎉 國定假日";
  badgeColor = "#00695C";
  badgeBg = "#E0F2F1";
  themeColor = "#00897B";
  isTriggered = true;
} else if (isLunchBreak) {
  displayTitle = "目前為午休時間";
  displayContent = "您好！目前正值午休時間，專員將於 13:00 過後儘速回覆您的訊息，謝謝您的耐心等候。";
  badgeText = "🍱 午休時間";
  badgeColor = "#E65100";
  badgeBg = "#FFF3E0";
  themeColor = "#EF6C00";
  isTriggered = true;
} else if (!isOfficeHour) {
  isTriggered = true;
}

// ==========================================
// 6. 事務所辦公時間資訊區塊
// ==========================================
const serviceHoursBox = {
  "type": "box",
  "layout": "vertical",
  "margin": "lg",
  "spacing": "sm",
  "backgroundColor": "#F8F9FA",
  "paddingAll": "md",
  "cornerRadius": "lg",
  "borderColor": "#EAEAEA",
  "borderWidth": "1px",
  "contents": [
    { "type": "text", "text": "🕒 事務所辦公時間", "weight": "bold", "size": "sm", "color": "#333333" },
    { "type": "separator", "margin": "xs", "color": "#EAEAEA" },
    {
      "type": "box",
      "layout": "horizontal",
      "margin": "sm",
      "contents": [
        { "type": "text", "text": "📅 辦公日期", "size": "sm", "color": "#777777", "flex": 3 },
        { "type": "text", "text": "每週一至週五", "size": "sm", "color": "#222222", "weight": "bold", "flex": 5 }
      ]
    },
    {
      "type": "box",
      "layout": "horizontal",
      "contents": [
        { "type": "text", "text": "⏰ 辦公時間", "size": "sm", "color": "#777777", "flex": 3 },
        { "type": "text", "text": "08:00～12:00\n13:00～17:00", "size": "sm", "color": "#222222", "wrap": true, "flex": 5 }
      ]
    },
    {
      "type": "box",
      "layout": "horizontal",
      "contents": [
        { "type": "text", "text": "📢 休假說明", "size": "sm", "color": "#777777", "flex": 3 },
        { "type": "text", "text": "國定假日與例假日依行政院人事行政總處公告放假", "size": "xs", "color": "#666666", "wrap": true, "flex": 5 }
      ]
    }
  ]
};

// ==========================================
// 7. LINE Flex Message 卡片裝配
// ==========================================
const flexMessage = {
  "type": "bubble",
  "direction": "ltr",
  "header": {
    "type": "box",
    "layout": "horizontal",
    "contents": [
      { "type": "text", "text": "系統自動回覆", "weight": "bold", "color": "#1DB446", "size": "xs", "gravity": "center" },
      {
        "type": "box",
        "layout": "horizontal",
        "contents": [
          { "type": "text", "text": badgeText, "size": "xs", "color": badgeColor, "weight": "bold", "align": "center" }
        ],
        "backgroundColor": badgeBg,
        "cornerRadius": "20px",
        "paddingAll": "xs",
        "paddingStart": "md",
        "paddingEnd": "md"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "spacing": "md",
    "contents": [
      {
        "type": "box",
        "layout": "horizontal",
        "spacing": "md",
        "contents": [
          {
            "type": "box",
            "layout": "vertical",
            "contents": [],
            "width": "4px",
            "backgroundColor": themeColor,
            "cornerRadius": "2px"
          },
          { "type": "text", "text": displayTitle, "weight": "bold", "size": "xl", "color": "#111111", "wrap": true }
        ]
      },
      { "type": "text", "text": displayContent, "size": "sm", "color": "#555555", "wrap": true },
      serviceHoursBox
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      { "text": "祝您有美好的一天！☀️", "type": "text", "style": "italic", "size": "sm", "color": "#AAAAAA", "align": "center" }
    ]
  }
};

// ==========================================
// 8. 回傳至 n8n 流程
// ==========================================
return {
  isOffWork: isTriggered,
  flexMessage: JSON.stringify(flexMessage)
};

// 1. 取得全域靜態儲存區
const staticData = $getWorkflowStaticData('global');

// 2. 安全地取得 userId
let userId;
try {
  // 這裡維持你原本的抓取方式
  userId = $('Line Messaging Trigger').first().json.source.userId;
} catch (e) {
  userId = null;
}

const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘

// 3. 如果抓不到 userId 的處理
if (!userId) {
  return {
    shouldReply: true, 
    isNewId: false,
    reason: "No userId found",
    userId: "unknown"
  };
}

// --- 【核心監聽邏輯】 ---
// 檢查這個 ID 是否不在暫存中（代表是新寫入，或是剛被早上 8 點清空後第一次出現）
const isNewId = !staticData[userId];
const tgNotifyMessage = isNewId ? `🔔 偵測到新暫存寫入！\nID: ${userId}\n時間: ${new Date().toLocaleString('zh-TW', {timeZone: 'Asia/Taipei'})}` : null;
// -----------------------

const lastReplyTime = staticData[userId];

// 4. 判斷冷卻時間
if (lastReplyTime && (now - lastReplyTime < COOLDOWN_MS)) {
    return { 
      shouldReply: false, 
      isNewId: false, // 已存在的 ID，不觸發監聽通知
      userId: userId,
      remainingTime: Math.round((COOLDOWN_MS - (now - lastReplyTime)) / 1000) + "s"
    };
} else {
    // 更新時間戳
    staticData[userId] = now;
    return { 
      shouldReply: true, 
      isNewId: isNewId, // 將監聽結果傳給下一個節點
      tgNotifyMessage: tgNotifyMessage,
      userId: userId 
    };
}

// 1. 取得上一個節點 (Aggregate 節點) 的資料
// 根據您的 Input，欄位名稱為 client_name 與 extra_invoice_link
const input = items[0].json;
const clients = Array.isArray(input.client_name) ? input.client_name : [input.client_name];
const baseLinks = Array.isArray(input.extra_invoice_link) ? input.extra_invoice_link : [input.extra_invoice_link];

// 2. 取得 Line Messaging Trigger 的 userId
// 注意：如果您的觸發節點名稱不同，請修改字串內容
const userId = $node["Line Messaging Trigger"].json.source.userId;

// 3. 動態生成按鈕
const buttons = clients.map((name, index) => {
  const link = baseLinks[index] || "";

  // 串接 uid 參數
  // 檢查原始連結是否已有問號，動態決定用 & 或 ?
  const finalUri = link.includes('?') 
    ? `${link}&uid=${userId}` 
    : `${link}?uid=${userId}`;

  return {
    "type": "button",
    "action": {
      "type": "uri",
      "label": String(name).substring(0, 40), // LINE 標籤限制 40 字元
      "uri": finalUri
    },
    "style": "primary",
    "margin": "md",
    "color": "#00B900" // 統一使用 LINE 綠色
  };
});

// 4. 組裝 Flex Message
const flexContent = {
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "📋 加買發票申請",
        "weight": "bold",
        "size": "lg",
        "color": "#1DB446"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "請選擇對應的單位進行填寫：",
        "size": "md",
        "color": "#666666",
        "wrap": true,
        "margin": "none"
      },
      {
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "spacing": "sm",
        "contents": buttons // 將生成的按鈕清單放入
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "如誤按請直接忽略此訊息",
        "size": "md",
        "color": "#FF0000",
        "align": "center"
      }
    ]
  }
};

return {
  flexJsonString: JSON.stringify(flexContent)
};

// 1. 獲取 LINE Trigger 的輸入資料
const input = $('Line Messaging Trigger').item.json;

// 2. 檢查是否為 Postback 類型且包含 data
if (input.type === 'postback' && input.postback && input.postback.data) {
  const data = input.postback.data;

  // 檢查開頭是否為 action=download
  if (data.startsWith("action=download")) {
    let clientNames = [];

    // 使用正則表達式提取 action=download= 或 clients= 後方的內容
    const match = data.match(/(?:action=download=|clients=)([^&]+)/);

    if (match && match[1]) {
      // 解碼 URI（處理中文與特殊符號），並依照逗號分割
      const clientsRaw = decodeURIComponent(match[1]);
      clientNames = clientsRaw.split(/[,，]\s*/)
                              .filter(name => name.trim().length > 0);
    }

    return {
      status: "success",
      clientNames: clientNames,
      count: clientNames.length,
      replyToken: input.replyToken,
      action: "download"
    };
  }
}

// 3. 若不符合 Postback 格式或 action 不符，回傳 ignore
return {
  status: "ignore",
  reason: "Not a valid download postback event"
};

// 1. 安全取得 Trigger 的 replyToken
let replyToken = '';
try {
  const triggerData = $('Line Messaging Trigger').first().json;
  replyToken = triggerData.replyToken || triggerData.body?.replyToken || '';
} catch (e) {
  replyToken = '';
}

for (const item of $input.all()) {
  try {
    // 2. 自動尋找包含 JSON 內容的欄位名稱
    const possibleKeys = ['JSON_Content', 'json_content', 'flex_json', 'JSON', 'json', 'content'];
    let rawContent = null;

    for (const key of possibleKeys) {
      if (item.json[key]) {
        rawContent = item.json[key];
        break;
      }
    }

    // 若上述名稱都沒對上，自動抓第一個「看起來像 JSON」的非 trigger_key 欄位
    if (!rawContent) {
      const keys = Object.keys(item.json);
      const dataKey = keys.find(k => k !== 'trigger_key' && k !== 'id' && item.json[k]);
      if (dataKey) {
        rawContent = item.json[dataKey];
      }
    }

    if (!rawContent) {
      const existingKeys = Object.keys(item.json).join(', ');
      throw new Error(`找不到 JSON 內容，目前欄位有：[${existingKeys}]`);
    }

    // 3. 解析 JSON 內容
    const parsed = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
    const payload = JSON.parse(JSON.stringify(parsed));

    // 4. 抽離 quickReply（如果有）
    const quickReply = payload.quickReply || undefined;
    if (payload.quickReply) {
      delete payload.quickReply;
    }

    // 5. 判斷 flex 內容結構 (carousel / bubble)
    let flexContents = payload;
    if (payload.type === 'carousel' || payload.type === 'bubble') {
      flexContents = payload;
    }

    // 6. 組裝出 LINE 官方 Message API 標準 Payload
    const messageObject = {
      type: "flex",
      altText: "您有一則新訊息",
      contents: flexContents
    };

    if (quickReply) {
      messageObject.quickReply = quickReply;
    }

    item.json.lineApiPayload = {
      replyToken: replyToken,
      messages: [messageObject]
    };

  } catch (error) {
    // 當發生格式錯誤時的防護回覆
    item.json.lineApiPayload = {
      replyToken: replyToken,
      messages: [
        {
          type: "text",
          text: `資料解析失敗：${error.message}`
        }
      ]
    };
  }
}

return $input.all();

