          ]
        }
      );
    } else {
      let currentNoticeList = [...noticeList];

      // 計算收帳日期的前一天
      const prevDateText = getPreviousDayText(rawDate);

      if (prevDateText && currentNoticeList.length > 0) {
        if (currentNoticeList[0].includes("提早一天")) {
          currentNoticeList[0] = currentNoticeList[0].replace("提早一天", `於${prevDateText}前`);
        } else {
          currentNoticeList[0] = `如需託收警衛，請於${prevDateText}前放置，並拍照告知。`;
        }
      }

      // 注意事項清單套用大一級字體 (lg)
      const noticeContents = currentNoticeList.map((text, idx) => ({
