        "size": "lg",
        "color": "#333333",
        "wrap": true,
        ...(idx > 0 ? { "margin": "sm" } : {})
      }));

      bodyContents.push(
        { "type": "separator", "margin": "lg" },
        {
          "type": "box",
          "layout": "vertical",
          "margin": "lg",
