            {
              "type": "box",
              "layout": "baseline",
              "spacing": "md",
              "contents": [
                { "type": "text", "text": "收發票日期", "size": "xl", "flex": 4, "color": "#333333" }, // 比例改為 4
                { "type": "text", "text": formattedDate, "wrap": true, "color": "#E63946", "size": "xl", "flex": 6, "weight": "bold" } // 比例改為 6
              ]
            },
            {
              "type": "box",
              "layout": "vertical",
              "margin": "md",
              "contents": noticeContents
            }
          ]
        },
        { "type": "separator", "margin": "lg" },
        {
          "type": "box",
          "layout": "vertical",
