// 從 Google 雲端硬碟連結中擷取資料夾 ID
function extractFolderId(url) {
  if (!url) return '';
  const match = url.match(/[-\w]{25,}/); // Drive ID 通常 25 碼以上
  return match ? match[0] : '';
}

const folderId = extractFolderId(driveLink);

