parameters.jsCode:
return [{
  json: $input.first().json,
  binary: $('HTTP Request3').first().binary
}];

// ============================================================
// ✅ 測試開關設定區（要測哪個情境，改這裡就好，不用動下面邏輯）
// ============================================================
const CONFIG = {
  // 無法辨識／對話截圖 → 保持靜默不回覆（這條維持真正靜默，不套用安全回覆）
  SILENT_ON_UNRECOGNIZED: true,

  // 本所帳單／請款單／收款明細表（客戶傳回本所帳單）→ 最高優先權，凌駕於匯款與憑證袋規則
  ENABLE_FIRM_BILL_REPLY: true,

  // 匯款對帳（命中指定帳號/姓名/轉帳卡片）→ true 發對帳文字，false 發安全回覆
  ENABLE_TRANSFER_REPLY: true,

  // 存摺內頁 → true 發「存摺內頁已儲存」，false 發安全回覆
  //ENABLE_PASSBOOK_REPLY: true,

  // 客戶交付／待收取憑證袋 → true 發「將派人前往收取」，false 發安全回覆
  ENABLE_PICKUP_BAG_REPLY: true,

  // 政府公文 → true 發公文專屬 Flex 卡片，false 發安全回覆
  ENABLE_GOVDOC_FLEX: true,

  // 作廢發票 → true 發作廢發票專屬 Flex 卡片，false 發安全回覆
  ENABLE_VOID_INVOICE_FLEX: true,

  // 發票（正常統一發票／其他發票憑證）→ true 發發票專屬 Flex 卡片，false 發安全回覆
  ENABLE_INVOICE_FLEX: true,

  // 一般憑證（合約、存摺封面、逐字稿等）→ true 發一般 Flex 卡片，false 發安全回覆
  //ENABLE_GENERAL_FLEX: true,

  // 分類關閉時，統一發送的安全回覆文字
  FALLBACK_TEXT: "您好，檔案已收到並存檔完成，後續將由專員為您確認，謝謝。",

  // 是否掛「我要通話」快捷按鈕
  ENABLE_QUICK_REPLY: true,

  // 只處理指定索引的檔案（從 0 開始），例如 [0, 2]；留空 [] = 全部處理
  SELECTED_INDEXES: []
};
// ============================================================

function getSafeNodeData(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
}

// 1. 安全取得前置節點資料
let codeDataList = getSafeNodeData('Code in JavaScript6');
let driveOriginalList = getSafeNodeData('Upload file1');
let driveTxtList = getSafeNodeData('Upload txt');
let txtGenList = getSafeNodeData('生成 TXT 檔');
const triggerDataList = getSafeNodeData('Line Messaging Trigger');

// 1-1. 依 SELECTED_INDEXES 篩選要處理的檔案（測試用）
if (Array.isArray(CONFIG.SELECTED_INDEXES) && CONFIG.SELECTED_INDEXES.length > 0) {
  codeDataList = CONFIG.SELECTED_INDEXES.map(i => codeDataList[i]).filter(Boolean);
  driveOriginalList = CONFIG.SELECTED_INDEXES.map(i => driveOriginalList[i]).filter(Boolean);
  driveTxtList = CONFIG.SELECTED_INDEXES.map(i => driveTxtList[i]).filter(Boolean);
  txtGenList = CONFIG.SELECTED_INDEXES.map(i => txtGenList[i]).filter(Boolean);
}

const firstTrigger = triggerDataList[0]?.json || {};
const replyToken = firstTrigger.replyToken || firstTrigger.body?.events?.[0]?.replyToken || '';
const totalCount = codeDataList.length;

if (totalCount === 0) {
  return [];
}

// 2. 無法辨識 / 對話截圖（這條維持真正靜默，不套用安全回覆）
const isUnrecognized = txtGenList.some(item => {
  const text = item.json?.aiText || item.json?.text || item.json?.output || "";
  return text.includes("無法辨識");
});
const isChatScreenshot = txtGenList.some(item => {
  const text = item.json?.aiText || item.json?.text || item.json?.output || "";
  return text.includes("對話截圖");
});

if (CONFIG.SILENT_ON_UNRECOGNIZED && (isUnrecognized || isChatScreenshot)) {
  return [];
}

// 3. 本所帳單／請款單／收款明細表（最高優先權，避免與對帳/戶名混淆）
const isFirmBill = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  return (
    aiText.includes("這張帳單") ||
    aiText.includes("收款明細表") ||
    aiText.includes("請款單") ||
    aiText.includes("金額或內容需要幫您確認") ||
    aiText.includes("確認或說明")
  );
});

// 4. 匯款帳號/姓名/轉帳憑證特徵比對
const targetAccounts = ['060508003687', '060508308968'];
const targetAccountHeads = ['0605'];
const targetAccountTails = ['03687', '08968'];

const hasTransferMatch = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  const cleanedText = aiText.replace(/[\s\-\_\(\)]/g, '');

  // A. 命中事務所指定帳號
  const matchFullAccount = targetAccounts.some(acc => cleanedText.includes(acc));
  const matchPartialAccount = targetAccountTails.some(tail => {
    if (!cleanedText.includes(tail)) return false;
    const hasHeadAndTail = targetAccountHeads.some(head => cleanedText.includes(head));
    if (hasHeadAndTail) return true;
    const idx = cleanedText.indexOf(tail);
    const before = cleanedText.slice(Math.max(0, idx - 6), idx);
    return /^[\dO○Ｏ*Xx•]+$/.test(before) && before.length >= 3;
  });

  // B. 命中事務所指定戶名
  const matchName =
    aiText.includes('陳銀鎮') ||
    aiText.includes('黃鈞煜') ||
    aiText.includes('陳Ｏ鎮') ||
    aiText.includes('陳○鎮') ||
    aiText.includes('陳O鎮') ||
    aiText.includes('陳Ｘ鎮') ||
    aiText.includes('陳X鎮') ||
    aiText.includes('黃Ｏ煜') ||
    aiText.includes('黃○煜') ||
    aiText.includes('黃O煜') ||
    aiText.includes('黃Ｘ煜') ||
    aiText.includes('黃X煜');

  // C. 命中匯款憑證/轉帳圖卡專屬特徵欄位（涵蓋客戶僅給末五碼或銀行截圖之情境）
  const matchTransferFields =
    aiText.includes('匯款金額') ||
    aiText.includes('末五碼') ||
    aiText.includes('末碼') ||
    aiText.includes('轉帳') ||
    aiText.includes('匯款人及帳號') ||
    aiText.includes('放行結果') ||
    aiText.includes('交易成功') ||
    aiText.includes('已轉') ||
    aiText.includes('已匯款');

  return matchFullAccount || matchPartialAccount || matchName || matchTransferFields;
});

// 5. 存摺內頁
const isPassbook = txtGenList.some(item => {
  const text = item.json?.aiText || item.json?.text || item.json?.output || "";
  return text.includes("存摺內頁已儲存");
});

// 6. 客戶交付／待收取憑證袋
const isPickupBag = txtGenList.some(item => {
  const text = item.json?.aiText || item.json?.text || item.json?.output || "";
  return text.includes("將派人前往收取");
});

// 7. 政府公文
const isGovDoc = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  return aiText.includes("發文機關") || aiText.includes("公文");
});

// 8. 作廢發票
const isVoidInvoice = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  return aiText.includes("狀態：作廢");
});

// 9. 發票（正常統一發票／其他發票憑證）
const isInvoice = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  return aiText.includes("賣方名稱") || aiText.includes("統一發票") || aiText.includes("此發票未打買受人統編");
});

let messagesArray = [];

// 共用 Flex 卡片產生器
function buildBubbles(headerLabelSingle) {
  return codeDataList.map((codeItem, index) => {
    const codeData = codeItem.json || {};
    const driveOriginal = driveOriginalList[index]?.json || {};
    const driveTxt = driveTxtList[index]?.json || {};
    const txtGenData = txtGenList[index]?.json || {};

    const aiText = txtGenData.aiText || txtGenData.text || txtGenData.output || "（目前系統繁忙，已完成備份，暫不提供 AI 即時解析服務。）";
    const fileLabel = codeData.originalFileName || `檔案_${index + 1}`;

    const originalUrl = driveOriginal.webViewLink || driveOriginal.webContentLink || '';
    const txtUrl = driveTxt.webViewLink || driveTxt.webContentLink || '';

    const bubbleObj = {
      type: "bubble",
      size: "kilo",
      header: {
        type: "box",
        layout: "horizontal",
        backgroundColor: "#F7F9FA",
        contents: [
          {
            type: "text",
            text: totalCount === 1 ? headerLabelSingle : `項目 (${index + 1}/${totalCount})`,
            weight: "bold",
            size: "sm",
            color: "#1DB446"
          },
          {
            type: "text",
            text: "已存檔 ☁️",
            size: "xs",
            color: "#888888",
            align: "end",
            gravity: "center"
          }
        ]
      },
      body: {
        type: "box",
        layout: "vertical",
        contents: [
          {
            type: "text",
            text: codeData.msgType === 'audio' ? `🎙️ ${fileLabel}` : `📁 ${fileLabel}`,
            weight: "bold",
            size: "md",
            color: "#0066CC",
            wrap: true
          },
          {
            type: "separator",
            margin: "md"
          },
          {
            type: "text",
            text: aiText,
            size: "xs",
            color: "#333333",
            wrap: true,
            margin: "md"
          }
        ]
      }
    };

    const footerLinks = [];
    if (txtUrl) {
      footerLinks.push({
        type: "text",
        text: "📄 TXT 文字檔",
        color: "#0066CC",
        size: "xs",
        align: "center",
        decoration: "underline",
        action: { type: "uri", uri: txtUrl }
      });
    }

    if (originalUrl) {
      footerLinks.push({
        type: "text",
        text: "📂 雲端原檔",
        color: "#0066CC",
        size: "xs",
        align: "center",
        decoration: "underline",
        action: { type: "uri", uri: originalUrl }
      });
    }

    if (footerLinks.length > 0) {
      bubbleObj.footer = {
        type: "box",
        layout: "horizontal",
        contents: footerLinks
      };
    }

    return bubbleObj;
  });
}

function pushBubblesAsMessages(allBubbles, altText) {
  for (let i = 0; i < allBubbles.length; i += 10) {
    const bubbleChunk = allBubbles.slice(i, i + 10);
    messagesArray.push({
      type: "flex",
      altText: altText,
      contents: {
        type: "carousel",
        contents: bubbleChunk
      }
    });
  }
  if (messagesArray.length > 4) {
    messagesArray = messagesArray.slice(0, 4);
  }
}

function pushFallback() {
  messagesArray.push({
    type: "text",
    text: CONFIG.FALLBACK_TEXT
  });
}

// 10. 依判斷出的分類 + 對應開關，決定要發完整內容還是安全回覆
// 🚨 優先權順序：isFirmBill 移至第一順位，保護帳單不被匯款關鍵字誤攔截
if (isFirmBill) {
  if (CONFIG.ENABLE_FIRM_BILL_REPLY) {
    messagesArray.push({
      type: "text",
      text: "您好，請問這張帳單是哪個項目的金額或內容需要幫您確認或說明嗎？"
    });
  } else {
    pushFallback();
  }
} else if (hasTransferMatch) {
  if (CONFIG.ENABLE_TRANSFER_REPLY) {
    messagesArray.push({
      type: "text",
      text: "✅ 已收到您的匯款資訊！\n對帳需人工核對（非即時），完成後將另行通知，感謝配合！"
    });
  } else {
    pushFallback();
  }
} else if (isPassbook) {
  if (CONFIG.ENABLE_PASSBOOK_REPLY) {
    messagesArray.push({ type: "text", text: "存摺內頁已儲存" });
  } else {
    pushFallback();
  }
} else if (isPickupBag) {
  if (CONFIG.ENABLE_PICKUP_BAG_REPLY) {
    messagesArray.push({ type: "text", text: "您好將派人前往收取，謝謝" });
  } else {
    pushFallback();
  }
} else if (isGovDoc) {
  if (CONFIG.ENABLE_GOVDOC_FLEX) {
    const allBubbles = buildBubbles("公文辨識摘要");
    pushBubblesAsMessages(allBubbles, "您的公文已自動儲存並完成解析");
    messagesArray.push({
      type: "text",
      text: "💡 提示：以上內容係由 AI 自動辨識，僅供快速參考，本所專員後續仍會開啟檔案查看。"
    });
  } else {
    pushFallback();
  }
} else if (isVoidInvoice) {
  if (CONFIG.ENABLE_VOID_INVOICE_FLEX) {
    const allBubbles = buildBubbles("⚠️ 作廢發票");
    pushBubblesAsMessages(allBubbles, "偵測到作廢發票");
    messagesArray.push({
      type: "text",
      text: "⚠️ 提醒：此張發票已標註「作廢」。"
    });
  } else {
    pushFallback();
  }
} else if (isInvoice) {
  if (CONFIG.ENABLE_INVOICE_FLEX) {
    const allBubbles = buildBubbles("發票憑證摘要");
    pushBubblesAsMessages(allBubbles, "您的發票已自動儲存並完成解析");
    messagesArray.push({
      type: "text",
      text: "💡 提示：以上內容係由 AI 自動辨識，僅供快速參考，本所專員後續仍會開啟檔案查看。"
    });
  } else {
    pushFallback();
  }
} else {
  // 一般憑證（合約、存摺封面、逐字稿等）
  if (CONFIG.ENABLE_GENERAL_FLEX) {
    const allBubbles = buildBubbles("憑證辨識摘要");
    pushBubblesAsMessages(allBubbles, "您的檔案已自動儲存並完成解析");
    messagesArray.push({
      type: "text",
      text: "💡 提示：以上內容係由 AI 自動辨識，僅供快速參考，本所專員後續仍會開啟檔案查看。"
    });
  } else {
    pushFallback();
  }
}

// 11. 掛上「我要通話」QuickReply（依開關）
if (CONFIG.ENABLE_QUICK_REPLY && messagesArray.length > 0) {
  const lastIndex = messagesArray.length - 1;
  messagesArray[lastIndex].quickReply = {
    items: [
      {
        type: "action",
        action: {
          type: "message",
          label: "我要通話",
          text: "我要通話"
        }
      }
    ]
  };
}

return [{
  json: {
    linePayload: {
      replyToken: replyToken,
      messages: messagesArray
    }
  }
}];

// 核心修正：直接向 Line Messaging Trigger 節點要原始 LINE 事件資料！
const item = $('Line Messaging Trigger').first().json;

// 1. 取得 replyToken
const replyToken = item.replyToken || item.body?.events?.[0]?.replyToken || '';

// 2. 取得 postback data
const postbackData = item.postback?.data || item.body?.events?.[0]?.postback?.data || item.data || item.text || '';

let folderId = '';
let folderName = '';
let companyId = '';
let companyName = '';

// 3. 解析當前點擊的資料夾 ID 與名稱
if (typeof postbackData === 'string' && postbackData.includes('folder_id=')) {
  folderId = postbackData.split('folder_id=')[1]?.split('&')[0] || '';
  if (postbackData.includes('folder_name=')) {
    const rawName = postbackData.split('folder_name=')[1]?.split('&')[0] || '';
    try { folderName = decodeURIComponent(rawName); } catch (e) { folderName = rawName; }
  }
}

// 4. 解析公司的根目錄 ID 與名稱
if (typeof postbackData === 'string' && postbackData.includes('company_id=')) {
  companyId = postbackData.split('company_id=')[1]?.split('&')[0] || '';
  if (postbackData.includes('company_name=')) {
    const rawCName = postbackData.split('company_name=')[1]?.split('&')[0] || '';
    try { companyName = decodeURIComponent(rawCName); } catch (e) { companyName = rawCName; }
  }
}

// 如果是第一次點擊公司選單，當下的 folder_id 即為 company_id
if (!companyId || companyId === '') {
  companyId = folderId;
  companyName = folderName;
}

return [
  {
    json: {
      replyToken: replyToken,
      folder_id: folderId,
      folder_name: folderName,
      company_id: companyId,
      company_name: companyName,
      raw_search_key: postbackData
    }
  }
];

return $input.all().map(item => {
  let prompt = item.json.systemPrompt || '';

  // 自動清除開頭與結尾的多餘反引號 ` 及空白
  prompt = prompt.replace(/^`+|`+$/g, '').trim();

  // 確保 binary 資料完整傳遞，並修復欄位名稱（避免跳出 no binary file 'data' 錯誤）
  const binaryData = item.binary || {};
  if (!binaryData.data && Object.keys(binaryData).length > 0) {
    const firstKey = Object.keys(binaryData)[0];
    binaryData.data = binaryData[firstKey];
  }

  return {
    json: {
      ...item.json,
      systemPrompt: prompt
    },
    binary: binaryData
  };
});

// 接在 Merge 節點之後：自動抓取不論是 Free 還是 Tier1 產出的辨識文字
const items = $input.all();
const codeDataList = $('Code in JavaScript6').all();

return items.map((item, index) => {
  const codeData = codeDataList[index]?.json || codeDataList[0]?.json || {};
  const mergedJson = item.json || {};

  // 1. 自動抓取 AI 辨識文字 (不論來自免費版或 Tier1)
  const aiText = mergedJson.candidates?.[0]?.content?.parts?.[0]?.text
              || mergedJson.content?.parts?.[0]?.text
              || mergedJson.text
              || "（目前無辨識文字）";

  // 2. 取原檔名並加上 _辨識摘要.txt
  const rawFileName = codeData.fileName || mergedJson.name || '憑證檔案.dat';
  const txtFileName = rawFileName.replace(/\.[^/.]+$/, "") + "_辨識摘要.txt";

  // 3. 轉成 UTF-8 二進位檔 (Binary Data)
  const buffer = Buffer.from(aiText, 'utf-8');

  return {
    json: {
      ...mergedJson,
      txtFileName: txtFileName,
      aiText: aiText
    },
    binary: {
      data: {
        data: buffer.toString('base64'),
        mimeType: 'text/plain',
        fileName: txtFileName,
        fileExtension: 'txt'
      }
    }
  };
});

const rawOutput = $input.first().json.output || $input.first().json;
const canAnswer = rawOutput.canAnswer ?? false;
const matchType = rawOutput.matchType || "exact";

const faqData = $('整理FAQ清單1').first().json;
const faqMap = faqData.faqMap || {};

const groupActionNames = {
  "GROUP_SETUP": "設立流程",
  "GROUP_NAME_CHANGE": "名稱變更",
  "GROUP_BUSINESS_CHANGE": "營業項目變更",
  "GROUP_ADDRESS_CHANGE": "地址變更",
  "GROUP_PERSON_CHANGE": "負責人/董監事變更",
  "GROUP_CAPITAL_INCREASE": "增資",
  "GROUP_CAPITAL_DECREASE": "減資",
  "GROUP_SUSPEND": "停業",
  "GROUP_RESUME": "復業",
  "GROUP_DISSOLVE": "解散歇業",
  "GROUP_COPY": "抄錄/補發資料",
  "GROUP_OTHER": "其他變更"
};

function getFlexFromMap(id) {
  if (!id) return null;
  const rawKey = String(id).trim();
  const withSlash = rawKey.startsWith('/') ? rawKey : '/' + rawKey;
  const withoutSlash = rawKey.replace(/^\//, '');

  if (faqMap[rawKey]) return faqMap[rawKey];
  if (faqMap[withSlash]) return faqMap[withSlash];
  if (faqMap[withoutSlash]) return faqMap[withoutSlash];

  return null;
}

function formatPostbackData(id) {
  if (!id) return "";
  const str = String(id).trim();
  if (/^\d+$/.test(str)) {
    return '/' + str;
  }
  return str;
}

function safeParseJson(str) {
  if (!str) return null;
  if (typeof str === 'object') return str;
  try {
    const cleaned = String(str).replace(/[\r\n]+/g, ' ').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}

function getShortLabel(label) {
  const str = String(label);
  if (str.includes("股份")) return "股份有限公司";
  if (str.includes("有限")) return "有限公司";
  if (str.includes("獨資")) return "獨資商業";
  if (str.includes("合夥")) return "合夥商業";
  return str.substring(0, 10);
}

function checkIsOffWorkNow() {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('zh-TW', { 
    timeZone: 'Asia/Taipei', 
    weekday: 'short', 
    hour: '2-digit', 
    minute: '2-digit', 
    hour12: false 
  });
  const parts = Object.fromEntries(formatter.formatToParts(now).map(p => [p.type, p.value]));
  const weekday = parts.weekday;
  const hour = parseInt(parts.hour, 10);

  if (weekday === '週六' || weekday === '週日') return true;

  const isMorning = (hour >= 8 && hour < 12);
  const isAfternoon = (hour >= 13 && hour < 17);

  return !(isMorning || isAfternoon);
}

let messages = [];

if (canAnswer) {
  if (matchType === "ambiguous" && Array.isArray(rawOutput.options) && rawOutput.options.length > 0) {
    const triggerData = $('Line Messaging Trigger').first().json;
    const userText = triggerData.message?.text || triggerData.postback?.data || "";

    const companyKeywords = ["公司", "有限公司", "股份有限公司"];
    const businessKeywords = ["行號", "商業", "工作室", "店家", "企業社", "商行", "店面"];

    const hasCompanyWord = companyKeywords.some(kw => userText.includes(kw));
    const hasBusinessWord = businessKeywords.some(kw => userText.includes(kw));

    const isCompanyOnly = hasCompanyWord && !hasBusinessWord;
    const isBusinessOnly = hasBusinessWord && !hasCompanyWord;

    let filteredOptions = rawOutput.options;

    if (isCompanyOnly) {
      filteredOptions = filteredOptions.filter(opt => {
        const idStr = formatPostbackData(opt.id);
        const labelStr = String(opt.label);
        return idStr.startsWith('/10') || idStr.startsWith('/20') || labelStr.includes("有限") || labelStr.includes("股份");
      });
    } else if (isBusinessOnly) {
      filteredOptions = filteredOptions.filter(opt => {
        const idStr = formatPostbackData(opt.id);
        const labelStr = String(opt.label);
        return idStr.startsWith('/30') || idStr.startsWith('/40') || labelStr.includes("獨資") || labelStr.includes("合夥");
      });
    }

    if (filteredOptions.length === 0) {
      filteredOptions = rawOutput.options;
    }

    const groupKey = rawOutput.ambiguousGroup || "";
    const standardAction = groupActionNames[groupKey] || rawOutput.actionName || "變更事項";
    const promptText = `請問您是指哪種組織型態的『${standardAction}』？`;

    messages.push({
      type: "text",
      text: promptText,
      quickReply: {
        items: filteredOptions.slice(0, 13).map(opt => {
          const displayLabel = getShortLabel(opt.label);
          return {
            type: "action",
            action: {
              type: "postback",
              label: displayLabel,
              displayText: displayLabel,
              data: formatPostbackData(opt.id)
            }
          };
        })
      }
    });

  } else if (matchType === "exact" || rawOutput.matchedId) {
    const targetId = String(rawOutput.matchedId || "").trim();
    const userText = $('Line Messaging Trigger').first().json.message?.text || "";

    const isTransferIntent = targetId === "匯款通知";
    const isReportGuideIntent = targetId === "詢問報表引導";

    if (isTransferIntent) {
      messages.push({
        type: "text",
        text: "✅ 已收到您的匯款資訊！\n對帳需人工核對（非即時），完成後將另行通知，感謝配合！"
      });
    } else if (isReportGuideIntent) {
      // 處理「我要報表」等模糊報表詢問，彈出引導 QuickReply 選單
      messages.push({
        type: "text",
        text: "「客戶資料夾」是儲存已經產生的歷史資料 (包含：401表、結算申報書、公司登記表、公司章程、商業抄本等等)。\n\n請問您是指哪一項？",
        quickReply: {
          items: [
            {
              type: "action",
              action: {
                type: "message",
                label: "📁 客戶資料夾",
                text: "客戶資料夾"
              }
            },
            {
              type: "action",
              action: {
                type: "message",
                label: "📊 暫結報表",
                text: "我要暫結報表"
              }
            }
          ]
        }
      });
    } else {
      let rawFlex = getFlexFromMap(targetId);

      if (rawFlex) {
        const flexContent = safeParseJson(rawFlex);

        if (flexContent) {
          messages.push({
            type: "flex",
            altText: flexContent.altText || "常見問題與服務回覆",
            contents: flexContent.type === "bubble" || flexContent.type === "carousel" 
                      ? flexContent 
                      : (flexContent.contents || flexContent)
          });
        }
      } else {
        const isOffWork = checkIsOffWorkNow();

        if (isOffWork) {
          const staticData = $getWorkflowStaticData('global');
          const triggerData = $('Line Messaging Trigger').first().json;
          const userId = triggerData.source?.userId || 'unknown';

          const now = Date.now();
          const COOLDOWN_MS = 5 * 60 * 1000;
          const lastReplyTime = staticData[userId] || 0;
          const isInCooldown = (now - lastReplyTime) < COOLDOWN_MS;

          if (!isInCooldown) {
            staticData[userId] = now;

            const offWorkFlex = $('Check Time & Holiday Logic2').first().json.flexMessage;
            const offWorkJson = typeof offWorkFlex === 'string' ? JSON.parse(offWorkFlex) : offWorkFlex;

            messages.push({
              type: "flex",
              altText: "非辦公時間通知",
              contents: offWorkJson
            });
          }
        }
      }
    }
  }
}

return {
  shouldSend: messages.length > 0,
  messages: messages
};

const rawFlex = $('Check Time & Holiday Logic2').first().json.flexMessage;
const flexMessageJson = typeof rawFlex === 'string' ? JSON.parse(rawFlex) : rawFlex;

return {
  messages: [
    {
      type: "flex",
      altText: flexMessageJson.body?.contents?.[0]?.text || "非辦公時間通知",
      contents: flexMessageJson
    }
  ]
};

const staticData = $getWorkflowStaticData('global');

let userId, userText;
try {
  const triggerData = $('Line Messaging Trigger').first().json;
  userId = triggerData.source?.userId || 'unknown';
  userText = triggerData.message?.text || '[非文字訊息/貼圖]';
} catch (e) {
  userId = 'unknown';
  userText = '[解析失敗]';
}

const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘冷卻期

const lastReplyTime = staticData[userId] || 0;
const isInCooldown = (now - lastReplyTime) < COOLDOWN_MS;

// 格式化台北時間
const timeStr = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

// 1. 每次下班時間有人傳訊息，都組合 Telegram 紀錄文字
const tgNotifyMessage = `🌙 <b>【下班時間客戶留言】</b>\n` +
  `<b>時間：</b>${timeStr}\n` +
  `<b>User ID：</b><code>${userId}</code>\n` +
  `<b>留言內容：</b>${userText}\n` +
  `<b>LINE 回覆狀態：</b>${isInCooldown ? '🔇 冷卻中（不重覆發送罐頭訊息）' : '✅ 已發送下班回覆'}`;

// 2. 若不在冷卻期，更新最後回覆時間
if (!isInCooldown) {
  staticData[userId] = now;
}

return {
  shouldReplyLine: !isInCooldown, // true 代表 LINE 要發送罐頭訊息
  tgNotifyMessage: tgNotifyMessage,
  userId: userId
};

const items = $input.all();
const faqMap = {};
const lines = [];
const keywordSet = new Set();

items.forEach((item, index) => {
  const rawCanAnswer = item.json['能否回答'];
  const isAllowed = rawCanAnswer === true ||
                    String(rawCanAnswer).trim().toUpperCase() === 'Y' ||
                    String(rawCanAnswer).trim().toUpperCase() === 'TRUE';

  if (isAllowed) {
    const id = String(item.json['row_number'] || (index + 2)).trim();
    const trigger = String(item.json['Trigger_Key (觸發關鍵字)'] || '').trim();
    const related = String(item.json['Related_Keywords (關聯詞)'] || '').trim();
    const jsonContent = item.json['JSON_Content (JSON 內容)'] || '';

    lines.push(`ID: ${id} | 關鍵字: ${trigger} | 關聯詞: ${related}`);

    if (jsonContent) {
      faqMap[id] = jsonContent;
      if (trigger) {
        faqMap[trigger] = jsonContent;
        const withSlash = trigger.startsWith('/') ? trigger : '/' + trigger;
        const withoutSlash = trigger.replace(/^\//, '');
        faqMap[withSlash] = jsonContent;
        faqMap[withoutSlash] = jsonContent;
      }
    }

    if (trigger) keywordSet.add(trigger.replace(/^\//, '').trim());
    if (related) {
      related.split(/[,、\s，]+/).forEach(k => {
        const cleaned = k.trim();
        if (cleaned) keywordSet.add(cleaned);
      });
    }
  }
});

return {
  faqText: lines.join('\n'),
  faqMap: faqMap,
  keywords: Array.from(keywordSet).filter(k => k.length >= 2)
};

