const targetAccounts = ['060508003687', '060508308968'];
// 前綴 4 碼與末 5 碼（可防範 0605***03687 這類僅露 5 碼的星號遮蔽）
const targetAccountHeads = ['0605'];
const targetAccountTails = ['03687', '08968'];

const hasTransferMatch = txtGenList.some(item => {
  const aiText = item.json?.aiText || "";
  const cleanedText = aiText.replace(/[\s\-\_\(\)]/g, '');

  // 1. 完整帳號比對
  const matchFullAccount = targetAccounts.some(acc => cleanedText.includes(acc));

  // 2. 帳號被遮蔽時的比對（支援末 5 碼與前綴 0605 / 遮蔽符號組合）
  const matchPartialAccount = targetAccountTails.some(tail => {
    if (!cleanedText.includes(tail)) return false;

    // 若包含前綴 0605 與末 5 碼即可判定命中
    const hasHeadAndTail = targetAccountHeads.some(head => cleanedText.includes(head));
    if (hasHeadAndTail) return true;

    // 或確認末 5 碼前方緊接著至少 3 個字元為數字或常見遮蔽符號（*、•、O、○、X等）
    const idx = cleanedText.indexOf(tail);
    const before = cleanedText.slice(Math.max(0, idx - 6), idx);
    return /^[\dO○Ｏ*Xx•]+$/.test(before) && before.length >= 3;
  });

  const matchAccount = matchFullAccount || matchPartialAccount;

  // 3. 姓名比對，涵蓋 O／○／Ｏ／X／Ｘ 等常見遮蔽符號
  const matchName =
