// 跨節點安全抓取資料工具函式
function tryGetNode(name) {
  try {
    const data = $(name).first().json;
    if (data && (data.company_name || data.folder_id || data.folder_name || data.replyToken)) return data;
  } catch (e) {}
  return null;
}

// 🎯 動態組合 URL（自動判斷要加 ? 還是 &）
function buildUrl(baseUrl) {
  if (!USE_EXTERNAL_BROWSER) return baseUrl;
  return baseUrl.includes('?') 
    ? `${baseUrl}&openExternalBrowser=1` 
    : `${baseUrl}?openExternalBrowser=1`;
}

// 1. 優先從子工作流呼叫節點（Call 客戶資料夾1 / Call 客戶資料夾）或上游讀取資料
const parseData = tryGetNode('Call 客戶資料夾1')
                || tryGetNode('Call 客戶資料夾')
                || tryGetNode('Execute Workflow Trigger')
                || tryGetNode('Code in JavaScript5')
                || tryGetNode('Code in JavaScript8')
                || tryGetNode('Code in JavaScript9')
                || ($input.first() ? $input.first().json : {});

// 2. 解析基本資訊
