// 1. 使用 $input.all() 取得所有輸入的 items
const items = $input.all();
const results = [];

// 2. 第一層迴圈：遍歷每一個 item
for (const item of items) {
  const fields = item.json;

  // 第二層迴圈：檢查該 item 的 1 到 10 的編號欄位
  for (let i = 1; i <= 10; i++) {
    const id = fields[`編號${i}`];
    if (id && typeof id === 'string' && id.trim() !== "") {
      results.push({ json: { "有效客戶編號": id.trim() } });
    }
  }
}

// 3. 若所有 items 都沒有綁定任何編號，才輸出特殊標記
if (results.length === 0) {
  return [{ json: { "有效客戶編號": "NONE", "未綁定": true } }];
}

return results;

// 1. 取得所有輸入項目與前置節點的完整陣列資料
const items = $input.all();
const triggerDataList = $('Line Messaging Trigger').all();
const httpDataList = $('HTTP Request3').all();
const sheetDataList = $('Get row(s) in sheet5').all();

// 2. 取得台北時間 (Asia/Taipei)
const now = new Date();
const timeZone = 'Asia/Taipei';
const yearMonthDay = new Intl.DateTimeFormat('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', timeZone }).format(now).replace(/\//g, '-');

// 3. 逐筆處理每一個 Item
return items.map((item, index) => {
  // 安全取得對應 Index 的資料（若未對齊則降級取第一筆）
  const triggerData = triggerDataList[index]?.json || triggerDataList[0]?.json || {};
  const message = triggerData.message || {};
  const userId = triggerData.source?.userId || '';
  const msgType = message.type || 'file';

  // 取得對應索引的 Binary 檔案實體
  const httpBinary = httpDataList[index]?.binary || item.binary || httpDataList[0]?.binary || {};

  // 從 Google Sheets 取得姓名
  let displayName = userId;
  try {
    const sheetData = sheetDataList[index]?.json || sheetDataList[0]?.json;
    if (sheetData) {
      displayName = sheetData['C:displayName'] || sheetData.displayName || sheetData.displayNan || userId;
    }
  } catch (e) {
    displayName = userId;
  }

  // 生成時間標記（若一次多張圖片，加上流水號 _1, _2 避免檔名覆蓋）
  const timeStr = new Intl.DateTimeFormat('zh-TW', { 
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone 
  }).format(now).replace(/:/g, '');
  const suffix = items.length > 1 ? `_${index + 1}` : '';

  // 自動判斷預設檔名
  let originalName = message.fileName;
  if (!originalName) {
    if (msgType === 'image') {
      originalName = `LINE_Image_${timeStr}${suffix}.jpg`;
    } else if (msgType === 'audio') {
      originalName = `LINE_Voice_${timeStr}${suffix}.m4a`;
    } else {
      originalName = `LINE_File_${timeStr}${suffix}.dat`;
    }
  }

  let finalFileName = `${displayName}_${originalName}`;

  return {
    json: {
      dayFolderName: yearMonthDay,
      fileName: finalFileName,
      originalFileName: originalName,
      userName: displayName,
      userId: userId,
      msgType: msgType
    },
    binary: httpBinary
  };
});

// 路線 B：轉換為 LINE 手機版與電腦版皆能正常顯示的 Google 原生圖片網址
const item = $input.first().json;
const fileId = item.clientNames;

// 改用 thumbnail 格式（解析度設為 w2000 保持高畫質）
const driveImageUrl = `https://drive.google.com/thumbnail?id=${fileId}&sz=w2000`;

return {
  JPG連結: [driveImageUrl],
  isDirectFile: true
};

// 1. 從源頭抓取 replyToken 與 userId
const triggerData = $('Line Messaging Trigger').first().json;
const replyToken = triggerData.replyToken;
const userId = triggerData.source.userId;

// 🌟 開關：要不要發送【匯款總額提醒】，改這裡 true / false 即可
const ENABLE_TOTAL_NOTICE = false ;

// 🌟 這個 userId 這次選擇/綁定了幾家客戶
const customerCount = Number($('發送LINE圖片').item.json.count) || 1;

// 2. 判斷路線
const inputData = $input.first() ? $input.first().json : {};
const isDirectFile = inputData.isDirectFile || false; // 🌟 辨識是否為補充文檔路線
const rawUrls = Array.isArray(inputData.JPG連結) ? inputData.JPG連結 : [];

// 只有在路線 A（正式帳單）才去抓取金額欄位
const rawAmounts = isDirectFile ? [] : (Array.isArray(inputData.總金額) ? inputData.總金額 : [inputData.總金額 || 0]);
const singleAmount = isDirectFile ? 0 : (Number(inputData.帳單金額) || 0);

// 3. 配對圖片與金額
const validPairs = [];
for (let i = 0; i < rawUrls.length; i++) {
  const url = String(rawUrls[i] || "").trim();
  if (url !== "" && url !== "尚未出帳") {
    validPairs.push({
      url: url,
      amount: isDirectFile ? 0 : (Number(rawAmounts[i]) || 0)
    });
  }
}

// 4. 若無合法圖片，回覆逾期提示
if (validPairs.length === 0) {
  return [{
    json: {
      endpoint: "https://api.line.me/v2/bot/message/reply",
      lineBody: {
        replyToken: replyToken,
        messages: [{
          type: "text",
          text: "【帳單下載期限已過提醒】\n\n您好，本期帳單已逾期無法下載。如需補發帳單，請直接聯絡專員為您處理，謝謝您！",
          quickReply: {
            items: [{ type: "action", action: { type: "message", label: "我要通話", text: "我要通話" } }]
          }
        }]
      }
    }
  }];
}

// 5. 組裝 LINE 圖片訊息
const allMessages = validPairs.map(p => {
  const secureUrl = String(p.url).replace("http://", "https://");
  return {
    "type": "image",
    "originalContentUrl": secureUrl,
    "previewImageUrl": secureUrl
  };
});

// 6. 計算合併總金額（去重複）
const uniqueAmounts = [...new Set(validPairs.map(p => p.amount).filter(a => a > 0))];
const totalAmount = uniqueAmounts.reduce((sum, p) => sum + p, 0);

// 7. 判斷是否需要補上總金額提醒
// 🌟 最前面加上 ENABLE_TOTAL_NOTICE 開關，關掉就完全不會發送
const shouldSendTotal = ENABLE_TOTAL_NOTICE
  && !isDirectFile
  && customerCount > 1
  && totalAmount > 0
  && (totalAmount !== singleAmount || validPairs.length >= 2);

if (shouldSendTotal) {
  let text = `✅【匯款總額提醒】\n`;
  if (validPairs.length === 1) {
    text += `此張帳單為您名下公司明細之一。\n`;
  } else {
    text += `您名下共 ${validPairs.length} 家公司帳單。\n`;
  }
  text += `💰 合計應匯款總金額為 NT$ ${totalAmount.toLocaleString()} 元。\n⚠️ 請確認總金額無誤後再進行匯款，以免遺漏。`;

  allMessages.push({
    "type": "text",
    "text": text
  });
}

// 8. 批次發送
const results = [];
const chunkSize = 5;
for (let i = 0; i < allMessages.length; i += chunkSize) {
  const chunk = allMessages.slice(i, i + chunkSize);
  if (i === 0) {
    results.push({
      json: {
        endpoint: "https://api.line.me/v2/bot/message/reply",
        lineBody: { replyToken: replyToken, messages: chunk }
      }
    });
  } else {
    results.push({
      json: {
        endpoint: "https://api.line.me/v2/bot/message/push",
        lineBody: { to: userId, messages: chunk }
      }
    });
  }
}
return results;

// 取得當前流進來的項目 (通過 Switch3 篩選的客戶)
const items = $input.all();

// ==========================================
// === 強化版：日期處理函數 (支援 9/8、9月8日) ===
// ==========================================
function getPreviousDayText(dateStr) {
  if (!dateStr || dateStr.includes("_")) return null;

  let month = null;
  let day = null;

  // 情況 1：格式為 "9月8日" 或類似中文字型
  const matchCN = dateStr.match(/(\d+)月\s*(\d+)日/);
  if (matchCN) {
    month = parseInt(matchCN[1], 10);
    day = parseInt(matchCN[2], 10);
  } else {
    // 情況 2：格式為 "9/8" 或 "2026/9/8"
    let cleanStr = dateStr.replace(/\s/g, "").trim();
    let parts = cleanStr.split("/");
    if (parts.length === 2) {
      month = parseInt(parts[0], 10);
      day = parseInt(parts[1], 10);
    } else if (parts.length === 3) {
      month = parseInt(parts[1], 10);
      day = parseInt(parts[2], 10);
    }
  }

  if (!month || !day) return null;

  // 用當年年份建立 Date 物件
  let d = new Date(new Date().getFullYear(), month - 1, day);
  if (isNaN(d.getTime())) return null; 

  // 減去一天 (自動處理跨月，例如 9月1日 變 8月31日)
  d.setDate(d.getDate() - 1);
  return `${d.getMonth() + 1}月${d.getDate()}日`;
}

