  if (isSendType && (!rawDate || rawDate === "____/____")) {
    return null; 
  }

  const formattedDate = rawDate.includes("/") 
    ? rawDate.replace("/", " 月 ") + " 日" 
    : rawDate;

  const bodyContents = [];

  if (sendType.includes("送發票")) {
    bodyContents.push(
      { "type": "text", "text": "親愛的客戶您好：", "size": "lg", "color": "#333333", "weight": "bold" },
      { "type": "separator", "margin": "lg" },
