      {
        "type": "box",
        "layout": "vertical",
        "margin": "md",
        "spacing": "xs",
        "contents": [
          { "type": "text", "text": "如有任何疑問，歡迎隨時與我們聯繫，謝謝！", "size": "lg", "color": "#333333", "wrap": true }
        ]
      }
    );
  } else {
    bodyContents.push({
      "type": "text",
      "text": "親愛的客戶您好：",
      "size": "lg",
      "color": "#333333",
      "weight": "bold"
    });

    if (dateOption === "自") {
      bodyContents.push(
        { "type": "separator", "margin": "lg" },
        {
          "type": "box",
