parameters.jsCode:
return [{
  json: $input.first().json,
  binary: $('HTTP Request3').first().binary
}];

// ============================================================
// ✅ 測試開關設定區（要測哪個情境，改這裡就好，不用動下面邏輯）
// ============================================================
const CONFIG = {
  // 無法辨識／對話截圖 → 保持靜默不回覆（這條維持真正靜默，不套用安全回覆）
  SILENT_ON_UNRECOGNIZED: true,

  // 本所帳單／請款單／收款明細表（客戶傳回本所帳單）→ 最高優先權，凌駕於匯款與憑證袋規則
  ENABLE_FIRM_BILL_REPLY: true,

  // 匯款對帳（命中指定帳號/姓名/轉帳卡片）→ true 發對帳文字，false 發安全回覆
  ENABLE_TRANSFER_REPLY: true,

  // 存摺內頁 → true 發「存摺內頁已儲存」，false 發安全回覆
  //ENABLE_PASSBOOK_REPLY: true,

  // 客戶交付／待收取憑證袋 → true 發「將派人前往收取」，false 發安全回覆
  ENABLE_PICKUP_BAG_REPLY: true,

  // 政府公文 → true 發公文專屬 Flex 卡片，false 發安全回覆
  ENABLE_GOVDOC_FLEX: true,

  // 作廢發票 → true 發作廢發票專屬 Flex 卡片，false 發安全回覆
  ENABLE_VOID_INVOICE_FLEX: true,

  // 發票（正常統一發票／其他發票憑證）→ true 發發票專屬 Flex 卡片，false 發安全回覆
  ENABLE_INVOICE_FLEX: true,

  // 一般憑證（合約、存摺封面、逐字稿等）→ true 發一般 Flex 卡片，false 發安全回覆
  //ENABLE_GENERAL_FLEX: true,

  // 分類關閉時，統一發送的安全回覆文字
  FALLBACK_TEXT: "您好，檔案已收到並存檔完成，後續將由專員為您確認，謝謝。",

  // 是否掛「我要通話」快捷按鈕
  ENABLE_QUICK_REPLY: true,

  // 只處理指定索引的檔案（從 0 開始），例如 [0, 2]；留空 [] = 全部處理
  SELECTED_INDEXES: []
};
// ============================================================

function getSafeNodeData(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
}

// 1. 安全取得前置節點資料
let codeDataList = getSafeNodeData('Code in JavaScript6');
let driveOriginalList = getSafeNodeData('Upload file1');
let driveTxtList = getSafeNodeData('Upload txt');
let txtGenList = getSafeNodeData('生成 TXT 檔');
const triggerDataList = getSafeNodeData('Line Messaging Trigger');

// 1-1. 依 SELECTED_INDEXES 篩選要處理的檔案（測試用）
if (Array.isArray(CONFIG.SELECTED_INDEXES) && CONFIG.SELECTED_INDEXES.length > 0) {
  codeDataList = CONFIG.SELECTED_INDEXES.map(i => codeDataList[i]).filter(Boolean);
  driveOriginalList = CONFIG.SELECTED_INDEXES.map(i => driveOriginalList[i]).filter(Boolean);
  driveTxtList = CONFIG.SELECTED_INDEXES.map(i => driveTxtList[i]).filter(Boolean);
  txtGenList = CONFIG.SELECTED_INDEXES.map(i => txtGenList[i]).filter(Boolean);
}

const firstTrigger = triggerDataList[0]?.json || {};
const replyToken = firstTrigger.replyToken || firstTrigger.body?.events?.[0]?.replyToken || '';
const totalCount = codeDataList.length;

if (totalCount === 0) {
  return [];
}

// 2. 無法辨識 / 對話截圖（這條維持真正靜默，不套用安全回覆）
const isUnrecognized = txtGenList.some(item => {
  const text = item.json?.aiText || item.json?.text || item.json?.output || "";
  return text.includes("無法辨識");
});
const isChatScreenshot = txtGenList.some(item => {
  const text = item.json?.aiText || item.json?.text || item.json?.output || "";
  return text.includes("對話截圖");
});

if (CONFIG.SILENT_ON_UNRECOGNIZED && (isUnrecognized || isChatScreenshot)) {
  return [];
}

// 3. 本所帳單／請款單／收款明細表（最高優先權，避免與對帳/戶名混淆）
const isFirmBill = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  return (
    aiText.includes("這張帳單") ||
    aiText.includes("收款明細表") ||
    aiText.includes("請款單") ||
    aiText.includes("金額或內容需要幫您確認") ||
    aiText.includes("確認或說明")
  );
});

// 4. 匯款帳號/姓名/轉帳憑證特徵比對
const targetAccounts = ['060508003687', '060508308968'];
const targetAccountHeads = ['0605'];
const targetAccountTails = ['03687', '08968'];

const hasTransferMatch = txtGenList.some(item => {
  const aiText = item.json?.aiText || item.json?.text || item.json?.output || "";
  const cleanedText = aiText.replace(/[\s\-\_\(\)]/g, '');

  // A. 命中事務所指定帳號
  const matchFullAccount = targetAccounts.some(acc => cleanedText.includes(acc));
  const matchPartialAccount = targetAccountTails.some(tail => {
    if (!cleanedText.includes(tail)) return false;
    const hasHeadAndTail = targetAccountHeads.some(head => cleanedText.includes(head));
    if (hasHeadAndTail) return true;
    const idx = cleanedText.indexOf(tail);
    const before = cleanedText.slice(Math.max(0, idx - 6), idx);
    return /^[\dO○Ｏ*Xx•]+$/.test(before) && before.length >= 3;
  });

  // B. 命中事務所指定戶名
  const matchName =
    aiText.includes('陳銀鎮') ||
    aiText.includes('黃鈞煜') ||
    aiText.includes('陳Ｏ鎮') ||
    aiText.includes('陳○鎮') ||
    aiText.includes('陳O鎮') ||
    aiText.includes('陳Ｘ鎮') ||
    aiText.includes('陳X鎮') ||
    aiText.includes('黃Ｏ煜') ||
    aiText.includes('黃○煜') ||
    aiText.includes('黃O煜') ||
    aiText.includes('黃Ｘ煜') ||
    aiText.includes('黃X煜');

  // C. 命中匯款憑證/轉帳圖卡專屬特徵欄位（涵蓋客戶僅給末五碼或銀行截圖之情境）
  const matchTransferFields =
    aiText.includes('匯款金額') ||
    aiText.includes('末五碼') ||
    aiText.includes('末碼') ||
    aiText.includes('轉帳') ||
    aiText.includes('匯款人及帳號') ||
    aiText.includes('放行結果') ||
    aiText.includes('交易成功') ||
    aiText.includes('已轉') ||
    aiText.includes('已匯款');

  return matchFullAccount || matchPartialAccount || matchName || matchTransferFields;
});

