parameters.jsCode:
const items = $input.all();

let replyToken = '';
let currentFolderName = "";
let currentFolderId = "";
let companyId = "";
let companyName = "";

// 跨節點安全抓取資料工具函式
function tryGetNode(name) {
  try {
    const data = $(name).first().json;
    if (data && (data.company_name || data.folder_id || data.folder_name || data.replyToken)) return data;
  } catch (e) {}
  return null;
}

// 1. 優先從子工作流呼叫節點（Call 客戶資料夾1 / Call 客戶資料夾）或上游讀取資料
const parseData = tryGetNode('Call 客戶資料夾1')
                || tryGetNode('Call 客戶資料夾')
                || tryGetNode('Execute Workflow Trigger')
                || tryGetNode('Code in JavaScript5')
                || tryGetNode('Code in JavaScript8')
                || tryGetNode('Code in JavaScript9')
                || ($input.first() ? $input.first().json : {});

// 2. 解析基本資訊
replyToken = parseData.replyToken || '';
companyName = parseData.company_name || parseData.folder_name || "客戶資料";
currentFolderName = parseData.folder_name || companyName;
if (currentFolderName === "雲端資料夾") currentFolderName = companyName;

currentFolderId = parseData.folder_id || "";
companyId = parseData.company_id || currentFolderId;

// ==========================================
// 檔名簡化格式化處理函式
// ==========================================
function formatFileName(fileName) {
  if (!fileName) return '';

  let displayName = fileName;

  const taxDeclarationMatch = displayName.match(/^(\d{3})(\d{2})_\d+_營業人銷售額與稅額申報書\((\d{3})\)/);
  if (taxDeclarationMatch) {
    const year = taxDeclarationMatch[1];
    const periodCode = taxDeclarationMatch[2];
    const taxFormType = taxDeclarationMatch[3];

    const periodMap = {
      '02': '01-02月',
      '04': '03-04月',
      '06': '05-06月',
      '08': '07-08月',
      '10': '09-10月',
      '12': '11-12月'
    };

    const monthStr = periodMap[periodCode] || `${periodCode}期`;
    const ext = displayName.substring(displayName.lastIndexOf('.'));

    return `${year}年${monthStr}${taxFormType}表${ext}`;
  }

  displayName = displayName.replace(/^[A-Z]\d{2}-?/i, '');
  displayName = displayName.replace(/\([^)]*\d{8}[^)]*\)/g, '');
  displayName = displayName.replace(/_?\d{8}_?/g, '');
  displayName = displayName.replace(/--+/g, '-');

  return displayName;
}

// 從檔名中擷取民國年份（限定 110~129 範圍）
function extractYear(name) {
  const matches = (name || '').match(/1[12]\d/g);
  if (!matches) return 0;
  return parseInt(matches[0], 10);
}

// 判斷「結算申報書」資料夾內，同年度檔案的顯示順序：稅簽 → 財簽 → 聲明書 → 其他
function getDocTypeOrder(name) {
  if (name.includes('稅簽')) return 0;
  if (name.includes('財簽聲明書')) return 2;
  if (name.includes('財簽')) return 1;
  return 3;
}

// ==========================================
// 「開啟雲端硬碟資料夾」按鈕
// ==========================================
function buildOpenDriveButton(folderId) {
  return {
    "type": "button",
    "action": {
      "type": "uri",
      "label": "📂 開啟雲端資料夾",
      "uri": `https://drive.google.com/drive/folders/${folderId}`
    },
    "style": "link",
    "height": "sm"
  };
}

// ==========================================
// 「返回」footer（子資料夾用）
// ==========================================
function buildBackFooter(companyId, companyName, currentFolderId) {
  return {
    "type": "box",
    "layout": "vertical",
    "contents": [
      buildOpenDriveButton(currentFolderId),
      {
        "type": "button",
        "action": {
          "type": "postback",
          "label": `🔙 返回 ${companyName}`,
          "data": `folder_id=${companyId}&folder_name=${companyName}&company_id=${companyId}&company_name=${companyName}`,
          "displayText": `🔙 返回 ${companyName}`
        },
        "style": "link",
        "height": "sm"
      }
    ]
  };
}

// ==========================================
// 「找不到文件」footer（根目錄用）
// ==========================================
function buildNotFoundFooter(currentFolderId) {
  return {
    "type": "box",
    "layout": "vertical",
    "contents": [
      buildOpenDriveButton(currentFolderId),
      {
        "type": "button",
        "action": {
          "type": "postback",
          "label": "找不到文件",
          "data": "/檔案不存在。",
          "displayText": "找不到我要的文件"
        },
        "style": "primary",
        "color": "#FF4B4B",
        "height": "sm"
      }
    ]
  };
}

function chunkArray(arr, chunkSize) {
  const chunks = [];
  for (let i = 0; i < arr.length; i += chunkSize) {
    chunks.push(arr.slice(i, i + chunkSize));
  }
  return chunks;
}

const fileItems = [];
const folderItems = [];

for (const item of items) {
  const file = item.json;
  if (!file || !file.id || !file.name) continue;

  const mimeType = file.mimeType || '';
  const isFolder = mimeType === 'application/vnd.google-apps.folder' || 
                   mimeType.includes('folder') || 
                   (!file.name.includes('.') && !file.webViewLink);

  if (isFolder) {
    folderItems.push(file);
  } else {
    fileItems.push(file);
  }
}

// ==========================================
// 401 申報書去重邏輯
// ==========================================
function getTaxDeclarationDedupInfo(name) {
  const m = (name || '').match(/^(\d{3})(\d{2})_\d+_營業人銷售額與稅額申報書\((\d{3})\)_?(\d)?_?\.[^.]+$/);
  if (!m) return null;
  return {
    key: `${m[1]}${m[2]}_${m[3]}`,
    suffix: m[4] || ''
  };
}

{
  const taxDeclMap = new Map();
  const nonTaxFiles = [];

  for (const file of fileItems) {
    const info = getTaxDeclarationDedupInfo(file.name);
    if (!info) {
      nonTaxFiles.push(file);
      continue;
    }

    const existing = taxDeclMap.get(info.key);
    if (!existing) {
      taxDeclMap.set(info.key, { file, suffix: info.suffix });
    } else if (info.suffix === '2' && existing.suffix !== '2') {
      taxDeclMap.set(info.key, { file, suffix: info.suffix });
    }
  }

  fileItems.length = 0;
  fileItems.push(...nonTaxFiles, ...Array.from(taxDeclMap.values()).map(v => v.file));
}

const isSettlementFolder = currentFolderName && currentFolderName.includes('結算申報書');

if (isSettlementFolder) {
  fileItems.sort((a, b) => {
    const yearA = extractYear(a.name);
    const yearB = extractYear(b.name);
    if (yearA !== yearB) return yearB - yearA;
    return getDocTypeOrder(a.name) - getDocTypeOrder(b.name);
  });

  const MAX_FILES = 72;
  if (fileItems.length > MAX_FILES) {
    fileItems.length = MAX_FILES;
  }
} else {
  fileItems.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'zh-Hant', { numeric: true }));
}

folderItems.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'zh-Hant', { numeric: true }));

const normalFolders = [];
const historyFolders = [];

for (const folder of folderItems) {
  if (folder.name && folder.name.includes('工商_歷史資料')) {
    historyFolders.push(folder);
  } else {
    normalFolders.push(folder);
  }
}

const sortedFolderItems = [...normalFolders, ...historyFolders];

const isAtCompanyRoot = (currentFolderId === companyId);

// 根目錄顯示公司名稱（如：廣伸企業有限公司）；子資料夾顯示：公司名稱 \n 子資料夾名稱
const headerTitle = (!isAtCompanyRoot && currentFolderName && currentFolderName !== companyName)
  ? `${companyName}\n${currentFolderName}`
  : companyName;

const bubbles = [];

if (fileItems.length === 0 && sortedFolderItems.length === 0) {
  const emptyBubble = {
    "type": "bubble",
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": "📂 資料夾內容", "weight": "bold", "size": "xs", "color": "#1DB446" },
        { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#333333", "wrap": true, "margin": "xs" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": "（此資料夾內目前沒有任何檔案或資料夾）", "color": "#888888", "align": "center", "size": "sm", "wrap": true, "margin": "md" }
      ]
    }
  };

  if (!isAtCompanyRoot) {
    emptyBubble.footer = buildBackFooter(companyId, companyName, currentFolderId);
  }

  bubbles.push(emptyBubble);

} else {
  if (fileItems.length > 0) {
    const fileChunks = isSettlementFolder ? chunkArray(fileItems, 6) : [fileItems];
    const totalPages = fileChunks.length;

    fileChunks.forEach((chunk, pageIndex) => {
      const fileContents = chunk.map((file) => {
        let fileUrl = '';
        const mimeType = file.mimeType || '';

        if (mimeType.includes('google-apps.document')) {
          fileUrl = `https://docs.google.com/document/d/${file.id}/export?format=pdf&openExternalBrowser=1`;
        } else if (mimeType.includes('google-apps.spreadsheet')) {
          fileUrl = `https://docs.google.com/spreadsheets/d/${file.id}/export?format=xlsx&openExternalBrowser=1`;
        } else {
          fileUrl = `https://drive.google.com/uc?export=download&id=${file.id}&openExternalBrowser=1`;
        }

        const displayFileName = formatFileName(file.name);

        return {
          "type": "box",
          "layout": "horizontal",
          "margin": "md",
          "paddingAll": "sm",
          "action": { "type": "uri", "uri": fileUrl },
          "contents": [
            { "type": "text", "text": `📄 ${displayFileName}`, "wrap": true, "color": "#0068FF", "size": "md" }
          ]
        };
      });

      const pageLabel = totalPages > 1 ? ` (${pageIndex + 1}/${totalPages})` : '';

      const fileBubble = {
        "type": "bubble",
        "header": {
          "type": "box",
          "layout": "vertical",
          "contents": [
            { "type": "text", "text": `📥 檔案點擊下載${pageLabel}`, "weight": "bold", "size": "xs", "color": "#1DB446" },
            { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#333333", "wrap": true, "margin": "xs" }
          ]
        },
        "body": { "type": "box", "layout": "vertical", "contents": fileContents }
      };

      if (!isAtCompanyRoot && pageIndex === totalPages - 1) {
        fileBubble.footer = buildBackFooter(companyId, companyName, currentFolderId);
      }

      bubbles.push(fileBubble);
    });
  } else {
    const fileBubble = {
      "type": "bubble",
      "header": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          { "type": "text", "text": "📄 檔案列表", "weight": "bold", "size": "xs", "color": "#1DB446" },
          { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#333333", "wrap": true, "margin": "xs" }
        ]
      },
      "body": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          { "type": "text", "text": "（此資料夾無獨立檔案）", "color": "#999999", "align": "center", "margin": "md", "size": "md" }
        ]
      }
    };

    if (!isAtCompanyRoot) {
      fileBubble.footer = buildBackFooter(companyId, companyName, currentFolderId);
    }

    bubbles.push(fileBubble);
  }

  if (sortedFolderItems.length > 0) {
    const folderContents = [];

    for (const file of sortedFolderItems) {
      folderContents.push({
        "type": "box",
        "layout": "horizontal",
        "margin": "sm",
        "paddingAll": "sm",
        "backgroundColor": "#F5F5F5",
        "cornerRadius": "md",
        "action": {
          "type": "postback",
          "data": `folder_id=${file.id}&folder_name=${file.name}&company_id=${companyId}&company_name=${companyName}`,
          "displayText": `📁 開啟 ${file.name}`
        },
        "contents": [
          { "type": "text", "text": `📁 ${file.name}`.substring(0, 20), "wrap": true, "color": "#555555", "size": "md" }
        ]
      });
    }

    const folderBubble = {
      "type": "bubble",
      "header": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          { "type": "text", "text": "📁 分類資料夾", "weight": "bold", "size": "xs", "color": "#1DB446" },
          { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#333333", "wrap": true, "margin": "xs" }
        ]
      },
      "body": { "type": "box", "layout": "vertical", "contents": folderContents }
    };

    folderBubble.footer = isAtCompanyRoot
      ? buildNotFoundFooter(currentFolderId)
      : buildBackFooter(companyId, companyName, currentFolderId);

    bubbles.push(folderBubble);
  }
}

let flexContent = {};

if (bubbles.length === 1) {
  flexContent = bubbles[0];
} else {
  flexContent = { "type": "carousel", "contents": bubbles };
}

return [
  {
    json: {
      replyToken: replyToken,
      flexObject: flexContent
    }
  }
];

//靜默不發送（不回覆）：辨識結果包含「無法辨識」或「對話截圖」時，回傳空陣列 []。

//匯款對帳純文字：辨識結果命中貴所帳號或姓名時，僅回覆「✅ 已收到您的匯款資訊！...」。

//一般憑證 Flex 卡片 (JSON)：其餘一般檔案，發送 Flex 輪播卡片＋結尾提示文字。

//共通快捷按鈕：只要最終有產生訊息，最後一則皆會掛載「我要通話」按鈕。



function getSafeNodeData(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
}

// 1. 安全取得前置節點資料
const codeDataList = getSafeNodeData('Code in JavaScript6');
const driveOriginalList = getSafeNodeData('Upload file1');
const driveTxtList = getSafeNodeData('Upload txt');
const txtGenList = getSafeNodeData('生成 TXT 檔');
const triggerDataList = getSafeNodeData('Line Messaging Trigger');

const firstTrigger = triggerDataList[0]?.json || {};
const replyToken = firstTrigger.replyToken || firstTrigger.body?.events?.[0]?.replyToken || '';
const totalCount = codeDataList.length;

// 2. 檢查圖片辨識結果是否為「無法辨識」或「對話截圖」
const isUnrecognized = txtGenList.some(item => (item.json?.aiText || "").includes("無法辨識"));
const isChatScreenshot = txtGenList.some(item => (item.json?.aiText || "").includes("對話截圖"));

// 3. 特殊圖檔（無法辨識 / 對話截圖）：不分上下班，一律保持靜默
if (isUnrecognized || isChatScreenshot) {
  return [];
}

// 4. 自動比對圖片 AI 辨識文字是否包含指定的收款帳號或收款人姓名（含遮蔽變體）
const targetAccounts = ['060508003687', '060508308968'];
// 前綴 4 碼與末 5 碼（可防範 0605***03687 這類僅露 5 碼的星號遮蔽）
const targetAccountHeads = ['0605'];
const targetAccountTails = ['03687', '08968'];

const hasTransferMatch = txtGenList.some(item => {
  const aiText = item.json?.aiText || "";
  const cleanedText = aiText.replace(/[\s\-\_\(\)]/g, '');

  // 1. 完整帳號比對
  const matchFullAccount = targetAccounts.some(acc => cleanedText.includes(acc));

  // 2. 帳號被遮蔽時的比對（支援末 5 碼與前綴 0605 / 遮蔽符號組合）
  const matchPartialAccount = targetAccountTails.some(tail => {
    if (!cleanedText.includes(tail)) return false;

    // 若包含前綴 0605 與末 5 碼即可判定命中
    const hasHeadAndTail = targetAccountHeads.some(head => cleanedText.includes(head));
    if (hasHeadAndTail) return true;

    // 或確認末 5 碼前方緊接著至少 3 個字元為數字或常見遮蔽符號（*、•、O、○、X等）
    const idx = cleanedText.indexOf(tail);
    const before = cleanedText.slice(Math.max(0, idx - 6), idx);
    return /^[\dO○Ｏ*Xx•]+$/.test(before) && before.length >= 3;
  });

  const matchAccount = matchFullAccount || matchPartialAccount;

  // 3. 姓名比對，涵蓋 O／○／Ｏ／X／Ｘ 等常見遮蔽符號
  const matchName =
    aiText.includes('陳銀鎮') ||
    aiText.includes('黃鈞煜') ||
    aiText.includes('陳Ｏ鎮') ||
    aiText.includes('陳○鎮') ||
    aiText.includes('陳O鎮') ||
    aiText.includes('陳Ｘ鎮') ||
    aiText.includes('陳X鎮') ||
    aiText.includes('黃Ｏ煜') ||
    aiText.includes('黃○煜') ||
    aiText.includes('黃O煜') ||
    aiText.includes('黃Ｘ煜') ||
    aiText.includes('黃X煜');

  return matchAccount || matchName;
});

let messagesArray = [];

if (hasTransferMatch) {
  // 💳 命中匯款單/轉帳截圖：只發送對帳通知，不發送 Flex 卡片與 AI 提示
  messagesArray.push({
    type: "text",
    text: "✅ 已收到您的匯款資訊！\n對帳需人工核對（非即時），完成後將另行通知，感謝配合！"
  });
} else {
  // 📁 一般可辨識憑證/檔案：正常發送 Flex 卡片與 AI 提示
  const allBubbles = codeDataList.map((codeItem, index) => {
    const codeData = codeItem.json || {};
    const driveOriginal = driveOriginalList[index]?.json || {};
    const driveTxt = driveTxtList[index]?.json || {};
    const txtGenData = txtGenList[index]?.json || {};

    const aiText = txtGenData.aiText || "（目前系統繁忙，已完成備份，暫不提供 AI 即時解析服務。）";
    const fileLabel = codeData.originalFileName || `檔案_${index + 1}`;

    const originalUrl = driveOriginal.webViewLink || driveOriginal.webContentLink || '';
    const txtUrl = driveTxt.webViewLink || driveTxt.webContentLink || '';

    const bubbleObj = {
      type: "bubble",
      size: "kilo",
      header: {
        type: "box",
        layout: "horizontal",
        backgroundColor: "#F7F9FA",
        contents: [
          {
            type: "text",
            text: totalCount === 1 ? "憑證辨識摘要" : `項目 (${index + 1}/${totalCount})`,
            weight: "bold",
            size: "sm",
            color: "#1DB446"
          },
          {
            type: "text",
            text: "已存檔 ☁️",
            size: "xs",
            color: "#888888",
            align: "end",
            gravity: "center"
          }
        ]
      },
      body: {
        type: "box",
        layout: "vertical",
        contents: [
          {
            type: "text",
            text: codeData.msgType === 'audio' ? `🎙️ ${fileLabel}` : `📁 ${fileLabel}`,
            weight: "bold",
            size: "md",
            color: "#0066CC",
            wrap: true
          },
          {
            type: "separator",
            margin: "md"
          },
          {
            type: "text",
            text: aiText,
            size: "xs",
            color: "#333333",
            wrap: true,
            margin: "md"
          }
        ]
      }
    };

    const footerLinks = [];
    if (txtUrl) {
      footerLinks.push({
        type: "text",
